mapper.select:
select c.htmlindex as interfFileType,
(select count(1) from chb_file_read_monitor_info a
where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
and DATE_FORMAT(a.FILE_READ_START_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}
and DATE_FORMAT(a.FILE_READ_END_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) as accessFilenum,
(select count(1) from chb_file_read_monitor_info a
where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
and a.FILE_HANDLE_STATUS = '03'
and DATE_FORMAT(a.FILE_READ_START_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}
and DATE_FORMAT(a.FILE_READ_END_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) as exceptionnum,
(select count(1) from chb_file_read_monitor_info a
where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
and a.FILE_HANDLE_STATUS = '02'
and DATE_FORMAT(a.FILE_READ_START_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}
and DATE_FORMAT(a.FILE_READ_END_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) as normalnum,
ifnull((select sum(ifnull(a.FILE_DATA_COUNT,0)) from chb_file_read_monitor_info a
where a.HANDLE_FILE_TYPE=b.HANDLE_FILE_TYPE
and a.FILE_HANDLE_STATUS = '02'
and DATE_FORMAT(a.FILE_READ_START_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}
and DATE_FORMAT(a.FILE_READ_END_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) ,0) as datanum
from (select '01' reportcode,'CHB_PRD_DECLARE' htmlindex from dual
union all select '02' reportcode,'CHB_PRD_BONUS_DEAL' htmlindex from dual
union all select '04' reportcode,'MST_HOLIDAY' htmlindex from dual
union all select '05' reportcode,'CHB_PRD_BASEINFO' htmlindex from dual
union all select '06' reportcode,'CHB_PRD_DEAL' htmlindex from dual
union all select '07' reportcode,'CHB_COUNTER_PARTY' htmlindex from dual
union all select '08' reportcode,'CHB_PRD_OPENSCH' htmlindex from dual
union all select '09' reportcode,'CHB_PRD_PERIODYIELD' htmlindex from dual
union all select '10' reportcode,'CHB_PRD_FEE_DEAL' htmlindex from dual
union all select '11' reportcode,'CHB_ASSET_INFO' htmlindex from dual
union all select '12' reportcode,'CHB_INVEST_TRADE' htmlindex from dual
union all select '13' reportcode,'CHB_BOT_AST_POS' htmlindex from dual
union all select '14' reportcode,'CHB_ASSET_INDEX' htmlindex from dual
union all select '15' reportcode,'CHB_SUBJECT_BALANCE' htmlindex from dual
union all select '16' reportcode,'MST_BOND_CREDIT_RATING' htmlindex from dual
union all select '17' reportcode,'MST_CUSTOMER_INFO' htmlindex from dual
union all select '18' reportcode,'CHB_CPROD_BALANCE' htmlindex from dual
union all select '19' reportcode,'SALE_CUST_SVRREPORT' htmlindex from dual
union all select '42' reportcode,'CHB_SALER_INST_INFO' htmlindex from dual
union all select '43' reportcode,'CHB_SALER_IDEN_INFO' htmlindex from dual
union all select '44' reportcode,'CHB_SALER_REW_PENA_INFO' htmlindex from dual
) c
left join chb_file_read_monitor_info b
on b.HANDLE_FILE_TYPE = c.reportcode
and DATE_FORMAT(b.FILE_READ_START_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}
and DATE_FORMAT(b.FILE_READ_END_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


group by b.HANDLE_FILE_TYPE,c.htmlindex
order by interfFileType desc

select a.INTERF_TYPE interfFileType, count(a.INTERF_TYPE) as datanum,
(select count(1) from CHB_INTERF_ERRODATA b
where b.INTERF_TYPE=a.INTERF_TYPE
and DATE_FORMAT(b.CREATE_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item.interfFileType,jdbcType=VARCHAR}


) as checkfailnum
from CHB_INTERF_ERRODATA a
where DATE_FORMAT(a.CREATE_TIME,'%Y-%m-%d') = #{searchDate,jdbcType=VARCHAR}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item.interfFileType,jdbcType=VARCHAR}


group by INTERF_TYPE

